with FilteredProducts as (select * from products where price > 940 and array_contains(tags, 'clearance')), summary as (select supplier_id, case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end as launch_cohort, round(stddev(price), 2) as stddev_price, sum(case when brand = 'Umbrella' then 1 else 0 end) as umbrella_count from FilteredProducts group by supplier_id, case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end) select supplier_id, launch_cohort, stddev_price, umbrella_count from summary where umbrella_count < 23 order by supplier_id desc;
